void GetNamedProperty(v8::Local<v8::Name> name, const v8::PropertyCallbackInfo<v8::Value>& info) {
    v8::Isolate* isolate = info.GetIsolate();
    v8::Local<v8::Object> holder = info.Holder();

    // Convert name to a string
    v8::Local<v8::String> nameString;
    if (!name->ToString(isolate->GetCurrentContext()).ToLocal(&nameString)) {
        return;
    }

    // Retrieve the associated LocalDOMWindow from the holder
    LocalDOMWindow* window = nullptr;
    if (!holder->GetAlignedPointerFromInternalField(0, &window)) {
        return;
    }

    // Check if the window is attached to a frame
    if (window->IsAttached()) {
        Frame* frame = window->GetFrame();
        Node* node = frame->GetDocument()->GetElementById(nameString);

        if (node) {
            v8::Local<v8::Value> result;
            node->Wrap(isolate, &result);
            info.GetReturnValue().Set(result);
            return;
        }

        // Search for named items in the document
        Element* element = frame->GetDocument()->GetNamedItem(nameString);
        if (element) {
            v8::Local<v8::Value> result;
            element->Wrap(isolate, &result);
            info.GetReturnValue().Set(result);
            return;
        }
    }

    // Default fallback - not found
    info.GetReturnValue().Set(v8::Null(isolate));
}

void GetNamedProperty(v8::Local<v8::Name> name, const v8::PropertyCallbackInfo<v8::Value>& info) {
  v8::Isolate* isolate = info.GetIsolate();
  v8::Local<v8::Object> holder = info.Holder();

  // Check if name is a string
  if (!name->IsString()) {
    return;
  }

  v8::Local<v8::String> name_string = v8::Local<v8::String>::Cast(name);
  LocalDOMWindow* window = GetLocalDOMWindow(isolate, holder);

  if (!window || !window->IsAttached()) {
    return;
  }

  Frame* frame = window->GetFrame();
  if (!frame || !frame->GetDocument()) {
    return;
  }

  const AtomicString& name_atomic = ToCoreAtomicString(name_string);

  // Check for sub-frames
  if (frame->IsSubFrame()) {
    v8::Local<v8::Value> result;
    if (frame->HasNamedItem(name_atomic)) {
      Node* node = frame->GetNamedItem(name_atomic);
      result = ToV8(node, holder, isolate);
      info.GetReturnValue().Set(result);
      return;
    }
  }

  // Check for named items in the document
  if (frame->GetDocument()->HasNamedItem(name_atomic)) {
    Node* node = frame->GetDocument()->GetNamedItem(name_atomic);
    v8::Local<v8::Value> result = ToV8(node, holder, isolate);
    info.GetReturnValue().Set(result);
    return;
  }

  // No matching item found
  info.GetReturnValue().Set(v8::Null(isolate));
}

void GetNamedProperty(v8::Local<v8::Name> name, const v8::PropertyCallbackInfo<v8::Value>& info) {
  v8::Isolate* isolate = info.GetIsolate();
  v8::Local<v8::Value> result;
  LocalDOMWindow* window = GetLocalDOMWindow(isolate);

  if (!window || !window->IsAttached()) {
    return;
  }

  Frame* frame = window->GetFrame();
  if (!frame) {
    return;
  }

  v8::String::Value name_value(isolate, name);
  if (!name_value.ToCString()) {
    return;
  }

  String name_string = String::FromUTF8(name_value.ToCString());
  if (name_string.IsNull()) {
    return;
  }

  // Search for sub-frames with the given name
  Frame* sub_frame = frame->Tree().FindByLocalName(name_string);
  if (sub_frame) {
    result = ToV8(sub_frame->DomWindow(), isolate, info.Holder());
  }

  // If not found in frames, search for named items in the document
  if (result.IsEmpty()) {
    Node* node = frame->GetDocument()->GetElementById(name_string);
    if (node) {
      result = ToV8(node, isolate, info.Holder());
    }
  }

  if (!result.IsEmpty()) {
    info.GetReturnValue().Set(result);
  }
}

void GetNamedProperty(v8::Local<v8::Name> name, const v8::PropertyCallbackInfo<v8::Value>& info) {
  v8::Isolate* isolate = info.GetIsolate();
  LocalDOMWindow* window = ToLocalDOMWindow(info.Holder());
  if (!window)
    return;

  Frame* frame = window->GetFrame();
  if (!frame)
    return;

  String string_name = v8_string_to_string(name);
  if (string_name.IsNull())
    return;

  DOMWindow* result = nullptr;
  if (frame->IsLocalFrame()) {
    LocalFrame* local_frame = ToLocalFrame(frame);
    result = local_frame->FindSubframe(string_name);
  }

  if (!result) {
    Document* document = frame->GetDocument();
    if (document)
      result = document->GetElementById(string_name).To<DOMWindow>();
  }

  if (result)
    info.GetReturnValue().Set(DOMWindow::Create(isolate, result));
}

void GetNamedProperty(v8::Local<v8::Name> name, const v8::PropertyCallbackInfo<v8::Value>& info) {
  v8::Isolate* isolate = info.GetIsolate();
  v8::Local<v8::Value> result;

  // Check if the name is a string
  if (!name->IsString()) {
    return;
  }

  v8::Local<v8::String> name_str = v8::Local<v8::String>::Cast(name);
  LocalDOMWindow* window = ToLocalDOMWindow(info.Holder());

  if (!window || !window->IsAttached()) {
    return;
  }

  // Retrieve frame and document
  Frame* frame = window->GetFrame();
  if (!frame) {
    return;
  }

  Document* document = frame->GetDocument();
  if (!document) {
    return;
  }

  // Search for sub-frames and named items in the document
  const NamedNodeMap* named_items = document->GetNamedItems(name_str);
  if (named_items && named_items->length() > 0) {
    Element* element = named_items->item(0);
    if (element) {
      result = v8::External::New(isolate, element);
    }
  }

  if (!result.IsEmpty()) {
    info.GetReturnValue().Set(result);
  }
}
